struct MessageFilter {
    virtual ~MessageFilter() {}
    virtual bool accept(const Message& m) const = 0;
};
class TypeFilter : public MessageFilter {
    std::string type_;
public:
    explicit TypeFilter(const std::string& t) : type_(t) {}
    bool accept(const Message& m) const { return m.header("type") == type_; }
};
